\set ON_ERROR_STOP on
create function public.test_assert(ok boolean,label text) returns void language plpgsql as $$ begin if not coalesce(ok,false) then raise exception 'FAIL: %',label;end if; raise notice 'PASS: %',label; end $$;
create function public.test_denied(stmt text,label text) returns void language plpgsql as $$ begin begin execute stmt; exception when others then raise notice 'PASS: % [rejected: %]',label,SQLERRM; return; end; raise exception 'FAIL: % unexpectedly accepted',label;end $$;
create function public.test_allowed(stmt text,label text) returns void language plpgsql as $$ begin execute stmt; raise notice 'PASS: %',label; exception when others then raise exception 'FAIL: % [error: %]',label,SQLERRM;end $$;
insert into auth.users values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222'),('33333333-3333-4333-8333-333333333333');
