-- Gated customer UPI offer: exact settled price/renewal policy stays separate from owner-only inputs.
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
set role authenticated;
select kdial_admin_save_listing('{"slug":"fictional-payment-offer","name":"Fictional Payment Fixture","category_slug":"cafes","locality_slug":"kaloor","address":"Fictional test-only address","phone":"+919876543210","description":"Fictional customer payment offer fixture."}') as offer_listing_id \gset
select kdial_admin_review_content(:'offer_listing_id',true,'Fictional test consent reference');
select kdial_admin_confirm_terms(:'offer_listing_id','Founder Package · first year',50100,current_date,current_date+365);
select test_denied(format('select kdial_admin_configure_payment_offer(%L,%L,%L)',:'offer_listing_id','','Fictional test refund wording'), 'customer offer rejects missing inclusions');
select kdial_admin_configure_payment_offer(:'offer_listing_id','Fictional test-only inclusion list.','Fictional test-only cancellation and refund wording.') as offer_token \gset
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select test_denied(format('select kdial_admin_configure_payment_offer(%L,%L,%L)',:'offer_listing_id','Fictional second inclusion text.','Fictional second refund wording.'), 'editor cannot create customer payment offer');
reset role;
set role anon;
select test_assert(kdial_public_payment_offer('99999999-9999-4999-8999-999999999999'::uuid) is null,'unknown token reveals no offer or QR');
select test_assert(kdial_public_payment_offer(:'offer_token'::uuid)->>'payee'='Felix Williams','only gated page identifies personal payee');
select test_assert(kdial_public_payment_offer(:'offer_token'::uuid)->>'upi_id'='7356137106@superyes','gated page uses the explicitly supplied temporary UPI ID');
select test_assert(kdial_public_payment_offer(:'offer_token'::uuid)->>'amount_minor'='50100','offer displays only the agreed ₹501 amount');
select test_assert(kdial_public_payment_offer(:'offer_token'::uuid)->>'first_year_label'='₹501 for the first year; the term begins on publication.','offer preserves publication-based first-year start');
select test_assert(kdial_public_payment_offer(:'offer_token'::uuid)->>'renewal_label'='₹701 manual renewal after the first year; no automatic charge.','offer states manual ₹701 renewal with no auto-charge');
select test_assert(length(kdial_public_payment_offer(:'offer_token'::uuid)->>'qr_base64')>100000,'gated offer serves the exact QR bytes only with its token');
select test_denied(format('select kdial_service_report_public_payment(%L,%L,%L)',:'offer_token',repeat('d',64),'FAKE-REF-123'),'anonymous users cannot call the service-only payment-report RPC');
reset role;
set role service_role;
select test_denied(format('select kdial_service_report_public_payment(%L,%L,%L)',:'offer_token',repeat('d',64),'bad ref'),'service RPC rejects unsafe reference characters');
select test_assert(kdial_service_report_public_payment(:'offer_token'::uuid,repeat('e',64),'TEST-REFERENCE-123')->>'status'='reported','CAPTCHA edge service can create only a report');
reset role;
select test_assert((select payment_status='reported' and bank_verified_at is null and bank_reference is null from kdial_private.listings where id=:'offer_listing_id'),'public report never becomes bank-verified');
select test_denied(format('select kdial_admin_publication(%L,''published'')',:'offer_listing_id'),'reported payment alone cannot publish listing');
reset role;
select 'GATED PAYMENT OFFER SECURITY TESTS COMPLETED' as result;
